{
  "name": "huggingchat-desktop",
  "version": "0.1.0",
  "description": "Minimal Windows desktop wrapper for HuggingChat",
  "main": "main.js",
  "author": "Josh",
  "license": "MIT",
  "scripts": {
    "start": "electron .",
    "dist": "electron-builder --win"
  },
  "devDependencies": {
    "electron": "latest",
    "electron-builder": "latest"
  },
  "build": {
    "appId": "com.josh.huggingchatdesktop",
    "productName": "HuggingChat Desktop",
    "directories": {
      "output": "dist"
    },
    "files": [
      "main.js",
      "package.json"
    ],
    "win": {
      "target": "nsis"
    },
    "nsis": {
      "oneClick": false,
      "allowToChangeInstallationDirectory": true,
      "createDesktopShortcut": true,
      "createStartMenuShortcut": true
    }
  }
}

const { app, BrowserWindow, shell } = require("electron");

let mainWindow = null;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1280,
    height: 850,
    minWidth: 800,
    minHeight: 600,
    title: "HuggingChat",
    autoHideMenuBar: true,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      sandbox: true
    }
  });

  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    try {
      const parsed = new URL(url);

      if (
        parsed.hostname === "huggingface.co" ||
        parsed.hostname.endsWith(".huggingface.co")
      ) {
        return { action: "allow" };
      }

      shell.openExternal(url);
      return { action: "deny" };
    } catch {
      return { action: "deny" };
    }
  });

  mainWindow.loadURL("https://huggingface.co/chat/");

  mainWindow.on("closed", () => {
    mainWindow = null;
  });
}

app.whenReady().then(() => {
  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});
